class Solution {
public:
    vector<int> getAllElements(TreeNode* root1, TreeNode* root2) {
        vector<int> result;
        stack<TreeNode*> s1, s2;

        pushLeft(root1, s1);
        pushLeft(root2, s2);

        while (!s1.empty() || !s2.empty()) {
            stack<TreeNode*>& s = (s1.empty() || (!s2.empty() && s2.top()->val < s1.top()->val)) ? s2 : s1;
            TreeNode* node = s.top();
            s.pop();
            result.push_back(node->val);
            pushLeft(node->right, s);
        }

        return result;
    }

private:
    void pushLeft(TreeNode* node, stack<TreeNode*>& s) {
        while (node) {
            s.push(node);
            node = node->left;
        }
    }
};
